import{_ as d,C as e,o as l,c as n,E as a,a2 as h}from"./chunks/framework.VWKgVqrc.js";const m=JSON.parse('{"title":"完成、合法与安全：三个指标为何不能互相代替","description":"","frontmatter":{"title":"完成、合法与安全：三个指标为何不能互相代替","date":"2026-11-04","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"多智能体的目标达成、交付验收、轨迹合法性与安全性，在哪些条件下会给出不同判断？","summary":"两个固定版本的评估模块显示，目标全达成可以与验收失败并存，合法计划也可以同时记录安全违规。合成输入揭示的是指标检查范围，不能当作完整系统复现。","sources":"固定版本的两篇论文、公开指标实现及同日内部模块实验","pageClass":"runtime-v6-article","item_id":"SIG-20261104-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-04-sig-20261104-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-04-sig-20261104-005.md","filePath":"zh/industry/2026-11-04-sig-20261104-005.md","lastUpdated":null}'),s={name:"zh/industry/2026-11-04-sig-20261104-005.md"};function o(c,t,p,g,b,u){const r=e("ArticleCover"),i=e("ArticleTableScroll");return l(),n("div",null,[a(r,{image:"/assets/covers/daily-2026-11-04-sig-20261104-005-cover.png",kicker:"研究成果",title:"完成、合法与安全：三个指标为何不能互相代替",summary:"两个固定版本的评估模块显示，目标全达成可以与验收失败并存，合法计划也可以同时记录安全违规。合成输入揭示的是指标检查范围，不能当作完整系统复现。",version:"2026-11-04",languageHref:"/en/industry/2026-11-04-sig-20261104-005",languageLabel:"English"}),a(i,{language:"zh"}),t[0]||(t[0]=h('<h1 id="完成、合法与安全-三个指标为何不能互相代替" tabindex="-1">完成、合法与安全：三个指标为何不能互相代替 <a class="header-anchor" href="#完成、合法与安全-三个指标为何不能互相代替" aria-label="Permalink to &quot;完成、合法与安全：三个指标为何不能互相代替&quot;">​</a></h1><p>一个任务的目标达成度为 1，验收结果却仍然失败。这并不一定是统计错误：目标是否做完，与原有内容是否被正确保留，可能是两项检查。另一个评估模块里，计划合法标志为真，也能同时出现一次安全违规。</p><p>这些差异来自本次内部实验：给固定版本的公开指标模块输入合成报告，观察各字段如何计算。对解读多智能体评估的工程师，更有用的问题是：一个字段究竟检查了什么，又留下了哪些没有回答的问题？本次分析认为，完成、验收、轨迹合法性和安全诊断必须保留各自的判断范围，不能让其中一个替其他字段背书。</p><p>这里的证据分为三类：论文中的实验属于作者报告；公开代码说明特定版本的计算规则；我们执行模块得到的结果属于内部实验依据，尚无独立复现者检验同一主张。下表的数值均为合成输入的模块输出，不是模型成功率或真实业务失败率。</p><h2 id="做完目标-为什么仍未通过验收" tabindex="-1">做完目标，为什么仍未通过验收 <a class="header-anchor" href="#做完目标-为什么仍未通过验收" aria-label="Permalink to &quot;做完目标，为什么仍未通过验收&quot;">​</a></h2><p>MAC-Bench（多智能体协作基准）的论文区分目标组进度与任务解决率。后者还需要满足适用的保留条件；一次正常结束也不自动等于任务解决。<a href="https://arxiv.org/html/2611.01728v1" target="_blank" rel="noreferrer">论文第 4.1 节及评估细节附录</a>提供的是作者的指标定义，不是所有业务环境的统一验收规范。</p><p>同日研究在固定的<a href="https://raw.githubusercontent.com/rzchen777-wq/MAC_Bench/1024991685762c54977ac45e1df4b6f6641a3e1b/src/mac_bench/evaluation/reports/metrics.py" target="_blank" rel="noreferrer">指标实现</a>上执行成对输入，得到以下内部实验结果。</p><table tabindex="0"><thead><tr><th>合成输入</th><th style="text-align:right;">目标达成度</th><th style="text-align:right;">进度分数</th><th>任务成功</th><th style="text-align:right;">解决率贡献</th></tr></thead><tbody><tr><td>已验收，目标全达成</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>真</td><td style="text-align:right;">1</td></tr><tr><td>验收失败，目标全达成</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>假</td><td style="text-align:right;">0</td></tr><tr><td>评估出错，输入仍带目标值 1</td><td style="text-align:right;">缺失</td><td style="text-align:right;">缺失</td><td>缺失</td><td style="text-align:right;">缺失</td></tr></tbody></table><p>来源：同日内部实验的验收通过、全进度但拒绝、评估不可用三个对照；全部使用合成报告。</p><p>关键边界在输入端：实验直接给出验收状态，并没有运行真实任务的验收器。因此它表明的是模块允许目标全达成与失败状态共存，而不是发现了一个自然发生的任务漏洞。</p><p>论文另有更接近任务语义的案例：作者报告，在一个模板处理任务中，五项任务目标已经完成，但原有错误元数据被破坏，保留条件因而失败。这个腐化与修复案例仍是<a href="https://arxiv.org/html/2611.01728v1" target="_blank" rel="noreferrer">论文第 4.4 节及腐化与修复附录</a>的作者证据，本次没有独立运行那个验收器。它说明为何需要保留条件；内部模块对照则说明该差异怎样在结果字段中被保留下来。两者不能合并称为一次端到端复现。</p><h2 id="合法计划的名字-比它检查的范围更宽" tabindex="-1">合法计划的名字，比它检查的范围更宽 <a class="header-anchor" href="#合法计划的名字-比它检查的范围更宽" aria-label="Permalink to &quot;合法计划的名字，比它检查的范围更宽&quot;">​</a></h2><p>CoCoBench（多智能体协作构念基准）的<a href="https://raw.githubusercontent.com/AgibotGeneral/CoCoBench/baa4dd5d9669251089c8d72ba7bb0532323b06a4/benchmark/eval/metrics.py" target="_blank" rel="noreferrer">固定指标代码</a>把最终成功、动作合法性、协作构念分数和安全违规分别计算。计划合法标志主要检查未获准技能与前置条件违规；它没有把所有安全诊断统一折入一个布尔值。</p><p>内部实验设置两个智能体，给其中一个声明可使用“打碎物体”技能，同时把目标物体声明为易碎对象。输入报告保留最终成功标志，两个智能体各有一次动作。模块输出：计划合法为真，负载分配构念分数为 1，安全违规数为 1。这里的分配分数描述动作分布，不能转译成安全分数。</p><p>对照进一步划定范围：改用未声明技能，计划合法变为假；一次被分类为“已经清洁”的无效交互不增加前置条件违规，而一次未被豁免的失败拾取交互会增加该计数。后者首先是报告分类器的输出，不能直接充当场景中真实失败原因的确认。</p><p>上述共存关系不是对上游实现的缺陷裁决。合成报告的最终成功由实验提供，并非模拟器或任务评分器产生。我们没有证明模拟器自然可达每一种输入组合。它支持的窄结论是：读者不能把“计划合法”扩写成“经过全面安全或授权认证”，也不能把高负载分配分数扩写成任务质量。</p><h2 id="缺失与样本不足-不能消失在平均数里" tabindex="-1">缺失与样本不足，不能消失在平均数里 <a class="header-anchor" href="#缺失与样本不足-不能消失在平均数里" aria-label="Permalink to &quot;缺失与样本不足，不能消失在平均数里&quot;">​</a></h2><p>同一套内部对照还检查了协作构念的参与门槛。</p><table tabindex="0"><thead><tr><th>合成轨迹</th><th>计划合法</th><th style="text-align:right;">构念分数</th><th>样本状态</th></tr></thead><tbody><tr><td>零次动作</td><td>缺失</td><td style="text-align:right;">缺失</td><td>没有动作</td></tr><tr><td>一次动作</td><td>真</td><td style="text-align:right;">缺失</td><td>信号不足</td></tr><tr><td>两个智能体各一次动作</td><td>真</td><td style="text-align:right;">1</td><td>参与样本数为 2，可评分</td></tr></tbody></table><p>来源：同日内部实验的零动作、单动作及双智能体均衡动作对照。</p><p>零动作不是合法性的反例，更不是合法性的通过证据；一次动作也不足以支持这个构念分数。<a href="https://arxiv.org/html/2608.28266v1" target="_blank" rel="noreferrer">构念定义与评分说明</a>中的参与条件因此必须与分数一起阅读。</p><p>验收模块的分母也值得单列：把一项通过、一项失败、一项评估不可用放在一起，内部实验得到两个可评分条目，解决率为 0.5、进度均值为 1，并另列一个评估不可用的排除项。不能把这个 0.5 写成三次尝试中的总体交付概率。排除并非天然错误；错误在于省略被排除的对象，让读者误认分母。</p><p>我们的工程解释是，评估输出应同时保留目标、验收、被测轨迹约束及证据覆盖。一个短字段需要附上实际谓词、适用对象和缺失处理，才能支持后续决策。两个基准的环境、任务和分母不同，这种比较不能形成合并成功率，也不能推出某种多智能体架构普遍更好或更差。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文依据同日已完成的研究对象和内部模块实验，没有在写作阶段开展新实验。模块固定于以下两个公开提交：多智能体协作基准为 <code>1024991685762c54977ac45e1df4b6f6641a3e1b</code>；协作构念基准为 <code>baa4dd5d9669251089c8d72ba7bb0532323b06a4</code>（公开提交标识）。前者执行了 5 个对照，后者执行了 7 个对照，均已通过。代码路径分别见前文链接；<a href="/joinwell52/assets/evidence/2026-11-04-sig-20261104-005/sig-20261104-005-evidence.json">内部实验输入、预期和实际输出</a>随候选材料保留。</p><p>公开来源的角色应分别理解：<a href="https://arxiv.org/html/2611.01728v1" target="_blank" rel="noreferrer">多智能体协作基准论文</a>提供目标、验收与保留条件的作者报告；<a href="https://arxiv.org/html/2608.28266v1" target="_blank" rel="noreferrer">协作构念基准论文</a>提供构念、合法性与任务成功的作者定义。两者的当前公开代码是可定位的实现事实，并不是检验同一性能主张的第三方独立证据。</p><p>发表不等于验证，引用不等于背书，同行评审不等于证明；来源自报不等于独立证据，模块实现成功不等于普遍有效。</p><h2 id="尚未回答的-是这些输入会怎样真实发生" tabindex="-1">尚未回答的，是这些输入会怎样真实发生 <a class="header-anchor" href="#尚未回答的-是这些输入会怎样真实发生" aria-label="Permalink to &quot;尚未回答的，是这些输入会怎样真实发生&quot;">​</a></h2><p>本次没有下载并执行完整任务包、原始运行档案或私有验收器，也没有运行具身模拟器。当前公开提交与论文原始实验版本未被证明逐行相同。上述结果不能测量自然发生频率，不能复现论文的成功率，更不能提供安全认证。</p><p>下一项需要研究的，是在固定任务和版本中，哪些报告组合确实可由执行轨迹产生，以及这些分离诊断怎样影响真实验收决定。在这些证据出现前，工程师可以保留并解释每项检查的范围；不能用一个听起来完整的指标名称，替代尚未执行的检查。</p>',30))])}const y=d(s,[["render",o]]);export{m as __pageData,y as default};
